/**
 * The recorded bounds of [the Lean fanout ratchet](./lean-fanout.test.ts). It counts, as
 * [`leanFanouts`](./lean-fanout.ts) finds them, only importers the semantic root builds, and exempts the declared
 * kernel; every module listed here may keep at most its recorded number of such importers, and every other module
 * at most `leanFanoutDefaultBound` (required item 6 of
 * [the build modularity specification](../docs/LEAN-BUILD-MODULARITY-PROPOSAL.md#contract)). The bounds are the
 * counts plus a tenth, at least ten, of the 2026-10-25 graph, tightened on 2026-10-26 after each module re-exported
 * only the modules its public declarations name, and re-derived the same day once the count learned that an
 * `import all` or `meta import` loads private imports too, so a new leaf module does not trip every module its
 * imports re-export, while a module that turns into a hub still fails. The list only shrinks: an entry whose module falls to
 * the default fails until it is removed, and raising a bound or adding an entry is a reviewed edit that records the
 * graph of the commit making it under the same rule.
 */

import type { LeanExposureAllowance, LeanFanoutBound, LeanOwnerDecidedRise } from "./lean-fanout.ts";

/**
 * Why the hidden-bodies conversion (owner decisions 1-3, 2026-10-29) raised a bound, by ratchet: each raised entry
 * below names one of these instead of repeating it.
 */
const hiddenBodiesConversion = {
  interface: "the hidden-bodies conversion (owner decisions 1-3, 2026-10-29): an `import all` importer loads the private imports of the module it opens, so the minimal `import all` lines (step C6) widen what loads this module",
  hidden: "the hidden-bodies conversion (owner decisions 1-3, 2026-10-29): importers whose proofs unfold this module's hidden bodies open it with `import all` (minimal, step C6), so a hidden edit reaches them and their `import all` loaders; bridge lemmas for edited hubs shrink it",
  body: "the hidden-bodies conversion (owner decisions 1-3, 2026-10-29): the body edit is now a hidden edit, which reaches the `import all` importers whose proofs unfold this module's bodies (minimal, step C6); bridge lemmas for edited hubs shrink it",
  rewrites: "the hidden-bodies conversion (owner decisions 1-3, 2026-10-29): rewrite sites the source model counts as an upper bound; the leak oracle (DumpLeaks, step E) finds exported equation lemmas only for the mutual block of CommandAdmission and, as before the conversion, `variableValueWellFormed` in the plain StructuredHumanWorkConformance",
  abbrevExposure: "the hidden-bodies conversion (owner decisions 1-3, 2026-10-29) replaced this module's `@[expose] public section`, which exported every body, with a plain one; these stay exported because Lean always exports an abbrev's body",
  propInstanceExposure: "the hidden-bodies conversion (owner decisions 1-3, 2026-10-29) replaced this module's `@[expose] public section`, which exported every body, with a plain one; the instance stays listed because the model counts every instance as exported, though its class is Prop-valued and Lean hides it (`bodyExported` cannot tell a Prop class)",
} as const;

